Rows look like shifted copies of each other (skill 1 rows 1 and 7 nearly match), so I will test whether each skill is f(a) op g(b) under add mod 16 or xor, with majority voting on the tables only and no weights touched.
```python
import numpy as np,json,pickle
rows=[json.loads(l) for l in open('answers.jsonl')]
Gs=[-np.ones((32,32),int) for _ in range(4)]
for r in rows: Gs[r['skill']][r['a'],r['b']]=r['answer']
np.save('G.npy',np.array(Gs))
ops={'add':(lambda x,y:(x+y)%16, lambda z,y:(z-y)%16),'xor':(lambda x,y:x^y, lambda z,y:z^y)}
def fit(G,op,inv,it=12):
    best=None
    for start in range(32):
        f=np.zeros(32,int); g=G[start].copy(); g[g<0]=0
        for _ in range(it):
            for a in range(32):
                m=G[a]>=0; c=np.bincount(inv(G[a][m],g[m]),minlength=16); f[a]=c.argmax()
            for b in range(32):
                m=G[:,b]>=0; c=np.bincount(inv(G[:,b][m],f[m]),minlength=16); g[b]=c.argmax()
        m=G>=0; ag=(op(f[:,None],g[None,:])==G)[m].mean()
        if best is None or ag>best[0]: best=(ag,f.copy(),g.copy())
    return best
res={}
for s in range(4):
    G=Gs[s]
    for n,(op,inv) in ops.items():
        ag,f,g=fit(G,op,inv); res[(s,n)]=(ag,f,g)
        print('skill',s,n,'agree %.3f'%ag); print(' f',f.tolist()); print(' g',g.tolist())
pickle.dump(res,open('fit.pkl','wb'))
