import numpy as np,json
Gs=np.load('G.npy')
def inv(s,z,y): return (z-y)%16 if s<3 else z^y
def fwd(s,x,y): return (x+y)%16 if s<3 else x^y
def solve(G,s):
    f=[None]*32; g=[None]*32; f[0]=0; todo=[('a',0)]
    while todo:
        k,i=todo.pop()
        if k=='a':
            for b in range(32):
                if G[i,b]>=0 and g[b] is None: g[b]=int(inv(s,G[i,b],f[i])); todo.append(('b',b))
        else:
            for a in range(32):
                if G[a,i]>=0 and f[a] is None: f[a]=int(inv(s,G[a,i],g[i])); todo.append(('a',a))
    return f,g
rng=np.random.default_rng(0); T={}
for s in range(4):
    G=Gs[s]; f,g=solve(G,s); m=G>=0
    pred=np.array([[fwd(s,x,y) for y in g] for x in f])
    print('skill',s,'solved',None not in f and None not in g,'wrong',int((pred[m]!=G[m]).sum()),'of',int(m.sum()))
    T[s]=(f,g)
    # rule check on pairs kept out of the derivation
    for rep in range(3):
        keep=m&(rng.random(G.shape)<0.7); H=np.where(keep,G,-1); f2,g2=solve(H,s)
        if None in f2 or None in g2: print('  not connected'); continue
        p2=np.array([[fwd(s,x,y) for y in g2] for x in f2]); out=m&~keep
        print('  kept-out wrong',int((p2[out]!=G[out]).sum()),'of',int(out.sum()))
json.dump({str(s):T[s] for s in T},open('tables.json','w'))
